    stage('Install Node.js Dependencies') {
        steps {
            dir('backend') {
                sh 'npm install'
            }
        }
    }
    stage('Install Python Dependencies') {
        steps {
            dir('frontend') {
                sh 'pip install -r requirements.txt'
            }
        }
    }
}
```

3. **pipelines/build.groovy**

```groovy
