### Optimized Pipeline Example

Here's an optimized version of your pipeline incorporating these best practices:

```groovy
pipeline {
    agent any

    environment {
        CACHE_PATH = '.cache'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Setup Environment') {
            steps {
                script {
                    def nodejs = tool name: 'NodeJS', type: 'org.jenkinsci.plugins.nodejs.tools.NodeJSInstallation'
                    env.PATH = "${nodejs}/bin:${env.PATH}"
                }
            }
        }

        stage('Cache Dependencies') {
            steps {
                script {
                    def cacheKey = "dependencies-${env.BRANCH_NAME}-${hashFiles('package-lock.json')}"
                    cache(path: "${env.CACHE_PATH}", key: cacheKey, restoreKeys: ['dependencies-${env.BRANCH_NAME}-'])
                }
            }
        }

        stage('Build') {
            parallel {
                stage('Build Backend') {
                    steps {
                        dir('backend') {
                            sh 'make build'
                        }
                    }
                }
                stage('Build Frontend') {
                    steps {
                        dir('frontend') {
                            sh 'make build'
                        }
                    }
                }
            }
        }

        stage('Test') {
            parallel {
                stage('Test Backend') {
                    steps {
                        dir('backend') {
                            sh 'make test'
                        }
                    }
                }
                stage('Test Frontend') {
                    steps {
                        dir('frontend') {
                            sh 'make test'
                        }
                    }
                }
            }
        }

        stage('Deploy') {
            when {
                expression { return env.BRANCH_NAME == 'main' }
