Jenkins jenkins = Jenkins.getInstance()

// Define the build failure rate threshold
def failureRateThreshold = 0.02

// Define the number of builds to check
def numBuilds = 40

// Define the network latency threshold in milliseconds
def networkLatencyThreshold = 90

// Function to measure network latency
def measureNetworkLatency(String host) {
    try {
        def start = System.currentTimeMillis()
        def socket = new Socket(host, 80)
        def end = System.currentTimeMillis()
        socket.close()
        return end - start
    } catch (IOException e) {
        println "Failed to measure latency to $host: ${e.message}"
        return -1
    }
}

// Function to check build results
def checkBuildResults() {
    def failureCount = 0

    // Loop through the builds and check the failure rate
    for (int i = 0; i < numBuilds; i++) {
        // Get the build result
        def buildResult = jenkins.getItemByFullName("YourJobName").getBuildByNumber(i + 1)

        // Check if the build failed
        if (buildResult?.result == Result.FAILURE) {
            // Increment the failure count
            failureCount++
        }
    }

    // Calculate the failure rate
    def failureRate = failureCount / numBuilds

    // Check if the failure rate exceeds the threshold
    if (failureRate > failureRateThreshold) {
        // Send an alert or take action
        println "Failure rate exceeds threshold! Current failure rate: ${failureRate * 100}%"
    } else {
        println "Current failure rate is within acceptable limits: ${failureRate * 100}%"
    }
}

// Function to monitor network latency
def monitorNetworkLatency(String host) {
    def latency = measureNetworkLatency(host)
    if (latency >= 0) {
        println "Network latency to $host: ${latency} ms"
        if (latency > networkLatencyThreshold) {
            println "High network latency detected! Latency exceeds threshold: ${latency} ms"
        }
    }
}

// Main script execution
