### Example Code

```python
from auth0.v3.authentication import GetToken
from auth0.v3.management import Auth0
import jwt

AUTH0_DOMAIN = 'my-auth0-domain.auth0.com'
AUTH0_CLIENT_ID = 'my-auth0-client-id'
AUTH0_CLIENT_SECRET = 'my-auth0-client-secret'
AUDIENCE = 'https://api.myapp.com/'

def authenticate_user(username, password):
    get_token = GetToken(AUTH0_DOMAIN)
    token = get_token.login(username, password, AUDIENCE)
    return token['access_token']

def validate_jwt(token):
    try:
        decoded_token = jwt.decode(token, options={"verify_signature": False})
        return decoded_token
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

def check_user_role(decoded_token):
    # Assuming roles are stored in the 'roles' claim of the JWT
    roles = decoded_token.get('roles', [])
    if 'admin' in roles:
        return True
    return False

# Example usage:
username = 'admin-user'
password = 'admin-password'
token = authenticate_user(username, password)
decoded_token = validate_jwt(token)

if decoded_token and check_user_role(decoded_token):
    print("User is authenticated and has admin role.")
else:
    print("User is not authenticated or does not have admin role.")
```

