    stages {
        stage('Build and Push') {
            steps {
                script {
                    def ecrPlugin = new com.amazonaws.jenkins.plugins.amazonecr.AmazonECR()
                    def repo = ecrPlugin.getRepository('your-repo-name')
                    def tag = "${env.BUILD_NUMBER}"
                    def image = "your-repo-name:${tag}"

                    sh "docker build -t ${image} ."
