        DOCKER_HUB_CREDENTIALS = credentials('docker-hub-credentials')
        KUBECONFIG = credentials('kubeconfig')
    }
    stages {
        stage('Build and Push') {
            steps {
                script {
                    def agent_ids = (1..30).toList()
                    agent_ids.each { agent_id ->
                        def latest_tag = "agent-${agent_id}:${new Date().format('yyyyMMddHHmmss')}"

                        sh """
                            docker build -t ${latest_tag} ./agents/${agent_id}
                            docker push ${latest_tag}
                        """

                        // Update ConfigMap
                        sh """
                            kubectl patch configmap image-tags -p '{"data": {"${"agent-${agent_id}:latest"}": "${latest_tag}", "${"agent-${agent_id}:previous"}": "$(kubectl get configmap image-tags -o jsonpath='{.data."agent-${agent_id}:latest"}')"}}}'
