            steps {
                sh 'kubectl apply -f deployment.yaml'
            }
        }
        stage('Rollback') {
            when {
                expression { currentBuild.resultIsWorseOrEqualTo('UNSTABLE') }
            }
            steps {
                script {
                    def agent_ids = (1..30).toList()
                    agent_ids.each { agent_id ->
                        def previous_tag = sh(script: "kubectl get configmap image-tags -o jsonpath='{.data.\"agent-${agent_id}:previous\"}'", returnStdout: true).trim()

                        sh """
                            docker pull ${previous_tag}
                            docker tag ${previous_tag} agent-${agent_id}
                        """

                        // Update ConfigMap
                        sh """
                            kubectl patch configmap image-tags -p '{"data": {"${"agent-${agent_id}:latest"}": "${previous_tag}", "${"agent-${agent_id}:previous"}": "$(kubectl get configmap image-tags -o jsonpath='{.data."agent-${agent_id}:latest"}')"}}}'
                        """
                    }
                }
            }
        }
    }
    post {
        always {
            archiveArtifacts artifacts: '**/*.log', allowEmptyArchive: true
        }
    }
}
