  image_id = "ami-0c55b159cbfafe1f0" # Replace with your AMI ID
  instance_type = "t2.micro"

  user_data = <<-EOF
              #!/bin/bash
              echo "Hello, World!" > /tmp/hello.txt
              EOF
}

# Define Auto Scaling Group
resource "aws_autoscaling_group" "example" {
  name                 = "example-asg"
  max_size             = 50
  min_size             = 1
  desired_capacity     = 50
  vpc_zone_identifier  = [aws_subnet.public[0].id, aws_subnet.public[1].id]
  launch_template {
    id      = aws_launch_template.example.id
    version = "$Latest"
  }
  tag {
    key                 = "Name"
    value               = "example-asg"
    propagate_at_launch = true
  }

  health_check_type = "ELB"
  health_check_grace_period = 300 # Grace period in seconds
}

# Define Target Group
resource "aws_lb_target_group" "example" {
  name     = "example-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id

  health_check {
    path                = "/healthcheck"
    interval            = 30
    timeout             =  5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }
}

# Define ALB
resource "aws_lb" "example" {
  name               = "example-alb"
  subnets            = [aws_subnet.public[0].id, aws_subnet.public[1].id]
  security_groups    = [aws_security_group.example.id]
  internal           = false
  load_balancer_type = "application"

  enable_cross_zone_load_balancing = true
  enable_deletion_protection       = false
}

# Define Listener
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.example.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example.arn
  }
}

# Define SSL Certificate Retrieval from Vault
resource "vault_generic_secret" "ssl_certificate" {
  path = "secret/data/alb-ssl-cert"
  data = {
    certificate = vault_generic_secret.ssl_certificate.data["certificate"]
    private_key = vault_generic_secret.ssl_certificate.data["private_key"]
  }
}

# Define HTTPS Listener
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.example.arn
  port              = "443"
  protocol          = "HTTPS"

  ssl_certificate_id = aws_acm_certificate.example.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example.arn
  }
}

# Define ACM Certificate
resource "aws_acm_certificate" "example" {
  domain_name       = "example.com"
  subject_alternative_names = ["*.example.com"]

  lifecycle {
    create_before_destroy = true
  }
}

# Request Validation for ACM Certificate
resource "aws_acm_certificate_validation" "example" {
  certificate_arn = aws_acm_certificate.example.arn
  validation_record_fqdns = [aws_route53_record.example.fqdn]
}

# Route53 Record for Domain Validation
resource "aws_route53_record" "example" {
  zone_id = "Z1234567890ABCDEF"
  name    = aws_acm_certificate.example.domain_validation_options[0].resource_record_name
  type    = aws_acm_certificate.example.domain_validation_options[0].resource_record_type
  records = [aws_acm_certificate.example.domain_validation_options[0].resource_record_value]
  ttl     = 60
}

# Attach Target Group to Auto Scaling Group
resource "aws_autoscaling_attachment" "example" {
  autoscaling_group_name = aws_autoscaling_group.example.name
  target_group_arn       = aws_lb_target_group.example.arn
}

# Enable Connection Draining
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.example.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example.arn
  }

  connection_draining {
    enabled = true
    timeout = 300 # Timeout in seconds
  }
}
```

### Explanation

1. **Subnets and Security Groups**: Defined multiple subnets and a security group to allow HTTP and HTTPS traffic.
2. **Launch Template and Auto Scaling Group**: Configured a launch template and an auto scaling group to manage backend instances.
3. **Target Group**: Defined a target group with health checks.
4. **ALB**: Configured the ALB with multiple subnets and enabled cross-zone load balancing.
5. **Listeners**: Defined both HTTP and HTTPS listeners. The HTTPS listener uses an ACM certificate.
6. **Vault Integration**: Retrieved SSL certificates from Vault and integrated them into the HTTPS listener.
7. **Connection Draining**: Enabled connection draining on the HTTP listener to ensure graceful termination of connections.

### Running the Configuration

To apply the configuration, run the following commands:

```sh
terraform init
terraform apply
```

This setup will optimize your ALB to handle 1,500 requests per second and ensure that your SSL certificates are securely managed using Vault. If you have any specific questions or need further assistance, feel free to ask!

Certainly! Implementing a canary deployment strategy involves rolling out new versions of your application to a small subset of instances first, then gradually expanding to the rest if everything goes well. Here's how you can set up a canary deployment strategy using Terraform and AWS Auto Scaling Groups.

### Step-by-Step Guide

1. **Define Launch Configurations**: Create two launch configurations, one for the canary instances and one for the main instances.
2. **Create Auto Scaling Groups**: Set up an Auto Scaling Group with a mix of canary and main instances.
3. **Use Target Groups**: Use separate target groups for canary and main instances.
4. **Configure Health Checks**: Ensure health checks are properly configured for both target groups.
5. **Monitor and Promote**: Monitor the canary instances and promote the new version if successful.

