  vpc_id   = aws_vpc.example.id

  health_check {
    path                = "/healthcheck"
    interval            =  30
    timeout             =  5
    healthy_threshold   =  2
    unhealthy_threshold =  2
  }
}

# Define Load Balancer
resource "aws_lb" "example" {
  name               = "example-lb"
  subnets            = [aws_subnet.public[0].id, aws_subnet.public[1].id]
  security_groups    = [aws_security_group.example.id]
  internal           = false
  load_balancer_type = "application"

  enable_cross_zone_load_balancing = true
  enable_deletion_protection       = false
}

# Define Listener
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.example.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "forward"
    forward {
      target_group {
        target_group_arn = aws_lb_target_group.canary.arn
        weight           = var.canary_weight
      }
      target_group {
        target_group_arn = aws_lb_target_group.main.arn
        weight           = var.main_weight
      }
    }
  }
}

# Define Auto Scaling Groups
resource "aws_autoscaling_group" "canary" {
  name                = "canary-asg"
  launch_configuration = aws_launch_configuration.canary.name
  min_size            = 1
  max_size            = 10
  desired_capacity    = 2
  vpc_zone_identifier = [aws_subnet.public[0].id, aws_subnet.public[1].id]

  health_check_type = "ELB"
  health_check_grace_period = 300 # Grace period in seconds

  tag {
    key                 = "Name"
    value               = "canary-asg"
    propagate_at_launch = true
  }
}

resource "aws_autoscaling_group" "main" {
  name                = "main-asg"
  launch_configuration = aws_launch_configuration.main.name
  min_size            = 1
  max_size            = 10
  desired_capacity    = 18
  vpc_zone_identifier = [aws_subnet.public[0].id, aws_subnet.public[1].id]

  health_check_type = "ELB"
  health_check_grace_period = 300 # Grace period in seconds

  tag {
    key                 = "Name"
    value               = "main-asg"
    propagate_at_launch = true
  }
}

# Attach Target Groups to Auto Scaling Groups
resource "aws_autoscaling_attachment" "canary" {
  autoscaling_group_name = aws_autoscaling_group.canary.name
  target_group_arn       = aws_lb_target_group.canary.arn
}

resource "aws_autoscaling_attachment" "main" {
  autoscaling_group_name = aws_autoscaling_group.main.name
  target_group_arn       = aws_lb_target_group.main.arn
}

# Define Variables
variable "canary_weight" {
  type    = number
  default = 50
}

variable "main_weight" {
  type    = number
  default = 50
}
```

### Explanation

1. **Target Groups**: Define separate target groups for canary and main instances.
2. **Load Balancer**: Set up an ALB with a listener that forwards traffic to both target groups.
3. **Dynamic Weight Adjustment**: Use Terraform variables (`var.canary_weight` and `var.main_weight`) to define the weights and update them as needed.

### Updating Weights Dynamically

To update the weights dynamically, you can simply change the values of the `canary_weight` and `main_weight` variables and re-run `terraform apply`.

For example, to shift more traffic to the main instances:

```hcl
variable "canary_weight" {
  type    = number
  default = 20
}

variable "main_weight" {
  type    = number
  default = 80
}
```

Then run:

```sh
terraform apply
```

### Conclusion

This configuration sets up a basic canary deployment strategy and provides a method to adjust the weights dynamically using Terraform variables. By updating the variables and re-running `terraform apply`, you can gradually shift traffic from canary to main instances. If you have any specific questions or need further assistance, feel free to ask!

