    Name = "public-sg"
  }
}

resource "aws_security_group" "private_sg" {
  name        = "private-sg"
  description = "Private Security Group"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "private-sg"
  }
}
```

### Step 5: Define Launch Configuration and Auto Scaling Group

Finally, define the launch configuration and auto scaling group, referencing the subnets and security groups.

```hcl
resource "aws_launch_configuration" "example" {
  name          = "example-lc"
  image_id      = "ami-0abcdef1234567890"  # Replace with your AMI ID
  instance_type = "t2.micro"               # Replace with your desired instance type
  security_groups = [aws_security_group.public_sg.id]

  user_data = <<-EOF
              #!/bin/bash
              echo "Hello, World!" > /index.html
              nohup python -m SimpleHTTPServer 80 &
              EOF
