To include backup success rates in your migration reports, you'll need to track both the number of successful and failed backups. You can then calculate the success rate based on these counts. Here's how you can modify your script to include this functionality:

### Step 1: Track Backup Success and Failure Counts

You can use a simple counter to keep track of the number of successful and failed backups. Additionally, you can store these counts in a persistent storage like a database or a file to maintain the counts across multiple runs.

### Step 2: Calculate Backup Success Rate

The backup success rate can be calculated as follows:

\[ \text{Backup Success Rate} = \left(\frac{\text{Number of Successful Backups}}{\text{Total Number of Backups}}\right) \times 100 \]

### Step 3: Modify Your Script

Below is an example of how you can modify your script to include backup success rate tracking and calculation:

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class BackupScript {
    public static void main(String[] args) {
        // Load database credentials from Vault
        String dbUrl = "jdbc:postgresql://localhost:5432/mydb";
        String dbUser = "myuser";
        String dbPassword = "mypassword";

        int successfulBackups = 0;
        int totalBackups = 0;

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {
            // Retrieve the current counts of successful and total backups
            successfulBackups = getSuccessfulBackupsCount(conn);
            totalBackups = getTotalBackupsCount(conn);

            // Perform backup using pgAdmin
            boolean backupSuccess = performBackup();

            // Update the counts based on the result of the backup
            if (backupSuccess) {
                successfulBackups++;
            }
            totalBackups++;

            // Store the updated counts back to the database
            updateBackupCounts(conn, successfulBackups, totalBackups);

            // Calculate the backup success rate
            double successRate = calculateSuccessRate(successfulBackups, totalBackups);

            // Log the success rate
            System.out.println("Backup Success Rate: " + successRate + "%");

        } catch (SQLException e) {
            // Handle database connection errors
            System.err.println("Error connecting to database: " + e.getMessage());
        }
    }

    private static boolean performBackup() {
        // Simulate the backup process
        // In a real scenario, you would replace this with actual backup logic
        return true; // Assume the backup was successful
    }

    private static int getSuccessfulBackupsCount(Connection conn) throws SQLException {
        PreparedStatement stmt = conn.prepareStatement("SELECT successful_backups FROM backup_stats");
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            return rs.getInt("successful_backups");
        }
        return 0;
    }

    private static int getTotalBackupsCount(Connection conn) throws SQLException {
        PreparedStatement stmt = conn.prepareStatement("SELECT total_backups FROM backup_stats");
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            return rs.getInt("total_backups");
        }
        return 0;
    }

    private static void updateBackupCounts(Connection conn, int successfulBackups, int totalBackups) throws SQLException {
        PreparedStatement stmt = conn.prepareStatement("UPDATE backup_stats SET successful_backups = ?, total_backups = ?");
        stmt.setInt(1, successfulBackups);
        stmt.setInt(2, totalBackups);
        stmt.executeUpdate();
    }

    private static double calculateSuccessRate(int successfulBackups, int totalBackups) {
        if (totalBackups == 0) {
            return 0.0;
        }
        return ((double) successfulBackups / totalBackups) * 100;
    }
}
```

