def load_config(file_path):
    with open(file_path, 'r') as f:
        return json.load(f)

# Function to create CloudWatch alarms based on the configuration
def create_cloudwatch_alarms(agents_config):
    cloudwatch = boto3.client('cloudwatch')

    for agent, metrics in agents_config['agents'].items():
        for metric_name, metric_config in metrics.items():
            alarm_name = f"{agent}_{metric_name}_alarm"
            alarm_description = f"Alarm for {metric_name} exceeding threshold for {agent}"

            cloudwatch.put_metric_alarm(
                AlarmName=alarm_name,
                ComparisonOperator=metric_config['comparison_operator'],
                EvaluationPeriods=metric_config['evaluation_periods'],
                MetricName=metric_name,
                Namespace=f"Agent/{agent}",
                Period=metric_config['period'],
                Statistic='Average',
                Threshold=metric_config['threshold'],
                ActionsEnabled=True,
                AlarmActions=['arn:aws:sns:region:account-id:topic-name'],  # Replace with actual SNS topic ARN
                AlarmDescription=alarm_description,
                Dimensions=[
                    {
                        'Name': 'Agent',
                        'Value': agent
                    }
                ]
            )
            print(f"Created CloudWatch alarm: {alarm_name}")

# Load alert thresholds configuration
alert_thresholds_config = load_config('alert_thresholds.json')

# Create CloudWatch alarms based on the configuration
create_cloudwatch_alarms(alert_thresholds_config)
