```python
import boto3

# Initialize AWS Backup and CloudWatch Events clients
backup = boto3.client('backup')
events = boto3.client('events')

# Define the event trigger
def create_event_trigger():
    # Create an event rule
    rule_name = 'backup-failure-rule'
    events.put_rule(
        Name=rule_name,
        EventPattern=json.dumps({
            "source": ["aws.backup"],
            "detail-type": ["Backup Job State Change"],
            "detail": {
                "state": ["FAILED"]
            }
        }),
        State='ENABLED'
    )

    # Create an event target
    target_name = 'backup-failure-target'
    lambda_function_arn = 'arn:aws:lambda:us-east-1:123456789012:function:my-lambda-function'
