                     subject: "Build ${env.BUILD_NUMBER} - ${currentBuild.result}",
                     body: """
                     Build ${env.BUILD_NUMBER} of ${env.JOB_NAME} has finished with result: ${currentBuild.result}.
                     Check the build details at ${env.BUILD_URL}.
                     """
            }
        }
    }

    post {
        always {
            cleanWs()
        }
    }
}
