### Full Python Script (`rollback_script.py`)

Here is the full Python script for clarity:

```python
import subprocess
from kubernetes import client, config
from kubernetes.client.rest import ApiException

# Load Kubernetes configuration
config.load_kube_config()

# Create a Kubernetes API client
api_instance = client.CoreV1Api()

def get_pod_status(namespace, pod_name):
    try:
        pod = api_instance.read_namespaced_pod(name=pod_name, namespace=namespace)
        return pod.status.phase
    except ApiException as e:
        print(f"Exception when calling CoreV1Api->read_namespaced_pod: {e}")
        return None

def force_terminate_pod(namespace, pod_name):
    try:
        api_instance.delete_namespaced_pod(name=pod_name, namespace=[namespace], body=client.V1DeleteOptions())
        print(f"Pod {pod_name} terminated.")
    except ApiException as e:
        print(f"Exception when calling CoreV1Api->delete_namespaced_pod: {e}")

def rollback_release(release_name, chart_name, namespace="default"):
    try:
        # Check if the release exists
        result = subprocess.run(["helm", "list", "--filter", release_name], capture_output=True, text=True)
        if release_name not in result.stdout:
            print(f"Release {release_name} not found.")
            return

        # Check for pods stuck in terminating state
        pods = api_instance.list_namespaced_pod(namespace)
        for pod in pods.items:
            if pod.metadata.labels and "app.kubernetes.io/name" in pod.metadata.labels and pod.metadata.labels["app.kubernetes.io/name"] == release_name:
                pod_status = get_pod_status(namespace, pod.metadata.name)
                if pod_status == "Terminating":
                    print(f"Pod {pod.metadata.name} is stuck in terminating state. Forcing termination...")
                    force_terminate_pod(namespace, pod.metadata.name)

        # Perform the rollback
        rollback_result = subprocess.run(["helm", "rollback", release_name, chart_name], capture_output=True, text=True)
        if rollback_result.returncode != 0:
            print(f"Rollback failed: {rollback_result.stderr}")
        else:
            print(f"Rollback successful: {rollback_result.stdout}")

    except Exception as e:
        print(f"An error occurred: {e}")

# Test the rollback function
if __name__ == "__main__":
    import sys
    rollback_release(sys.argv[1], sys.argv[2], sys.argv[3])
```

### Additional Considerations

- **Namespace**: Ensure the correct namespace is used for your deployment.
- **Labels**: Use appropriate labels to identify pods associated with the release.
- **Logging**: Add more detailed logging as needed to track the progress and any issues encountered.

By following these steps, you can effectively integrate the rollback script into your existing CI/CD pipeline, ensuring safer and smoother rollbacks for your multi-agent AI platform.

